import React, { useEffect, useRef } from 'react';
import { Streamlit } from 'streamlit-component-lib';
import { Html5QrcodeScanner } from 'html5-qrcode';

const BarcodeScannerComponent = () => {
  const scannerRef = useRef(null);

  useEffect(() => {
    // S'assure que le scanner n'est initialisé qu'une seule fois
    if (!scannerRef.current) {
      const onScanSuccess = (decodedText, decodedResult) => {
        console.log(`Code matched = ${decodedText}`, decodedResult);
        Streamlit.setComponentValue(decodedText);
        // Arrêter le scanner après un succès
        if (scannerRef.current) {
          scannerRef.current.clear();
        }
      };

      const onScanFailure = (error) => {
        // console.warn(`Code scan error = ${error}`);
      };

      const config = {
        fps: 10,
        qrbox: { width: 250, height: 150 },
        facingMode: "environment"
      };

      const html5QrcodeScanner = new Html5QrcodeScanner("reader", config, false);
      html5QrcodeScanner.render(onScanSuccess, onScanFailure);
      scannerRef.current = html5QrcodeScanner;
    }

    // Fonction de nettoyage pour s'assurer que le scanner est bien arrêté
    return () => {
      if (scannerRef.current) {
        scannerRef.current.clear().catch(error => {
          console.error("Failed to clear html5QrcodeScanner.", error);
        });
      }
    };
  }, []);

  // Ajuster la hauteur pour Streamlit
  useEffect(() => {
    Streamlit.setFrameHeight(400);
  });

  return <div id="reader" style={{ width: '100%' }} />;
};

export default BarcodeScannerComponent;
